changeSet.sql:
INSERT INTO course_configuration (backfill_owner_id, grade_relevant, data_retention_hold, auto_orchestrator_enabled)
            SELECT id, TRUE, FALSE, FALSE FROM course WHERE course_configuration_id IS NULL
            AND NOT EXISTS (SELECT 1 FROM course_configuration existing WHERE existing.backfill_owner_id = course.id);
            UPDATE course SET course_configuration_id =
                (SELECT config.id FROM course_configuration config WHERE config.backfill_owner_id = course.id)
            WHERE course_configuration_id IS NULL;

INSERT INTO course_athena_config (backfill_owner_id, grading_feedback_enabled, formative_feedback_enabled)
            SELECT id, FALSE, FALSE FROM course WHERE athena_config_id IS NULL
            AND NOT EXISTS (SELECT 1 FROM course_athena_config existing WHERE existing.backfill_owner_id = course.id);
            UPDATE course SET athena_config_id =
                (SELECT config.id FROM course_athena_config config WHERE config.backfill_owner_id = course.id)
            WHERE athena_config_id IS NULL;

INSERT INTO team_assignment_config (backfill_owner_id, min_team_size, max_team_size)
            SELECT id, 1, 1 FROM exercise WHERE team_assignment_config_id IS NULL
            AND NOT EXISTS (SELECT 1 FROM team_assignment_config existing WHERE existing.backfill_owner_id = exercise.id);
            UPDATE exercise SET team_assignment_config_id =
                (SELECT config.id FROM team_assignment_config config WHERE config.backfill_owner_id = exercise.id)
            WHERE team_assignment_config_id IS NULL;

INSERT INTO plagiarism_detection_config (backfill_owner_id, continuous_plagiarism_control_enabled, continuous_plagiarism_control_post_due_date_checks_enabled, continuous_plagiarism_control_case_student_response_period, similarity_threshold, minimum_score, minimum_size)
            SELECT id, FALSE, FALSE, 7, 90, 0, 50 FROM exercise WHERE plagiarism_detection_config_id IS NULL
            AND NOT EXISTS (SELECT 1 FROM plagiarism_detection_config existing WHERE existing.backfill_owner_id = exercise.id);
            UPDATE exercise SET plagiarism_detection_config_id =
                (SELECT config.id FROM plagiarism_detection_config config WHERE config.backfill_owner_id = exercise.id)
            WHERE plagiarism_detection_config_id IS NULL;

INSERT INTO online_course_configuration (course_id, user_prefix, require_existing_user)
            SELECT course.id, COALESCE(course.short_name, CONCAT('course', course.id)), FALSE FROM course
            WHERE NOT EXISTS (SELECT 1 FROM online_course_configuration config WHERE config.course_id = course.id);
            INSERT INTO tutorial_groups_configuration (course_id, use_tutorial_group_channels, use_public_tutorial_group_channels)
            SELECT course.id, FALSE, FALSE FROM course
            WHERE NOT EXISTS (SELECT 1 FROM tutorial_groups_configuration config WHERE config.course_id = course.id);
            INSERT INTO course_iris_settings (course_id, settings)
            SELECT course.id, '{"enabled":true,"variant":"default","supportLevel":"moderate"}' FROM course
            WHERE NOT EXISTS (SELECT 1 FROM course_iris_settings config WHERE config.course_id = course.id);
            INSERT INTO programming_exercise_build_config (exercise_id, timeout_seconds, allow_branching, branch_regex, checkout_solution_repository)
            SELECT exercise.id, 0, FALSE, '.*', FALSE FROM exercise WHERE exercise.discriminator = 'P'
            AND NOT EXISTS (SELECT 1 FROM programming_exercise_build_config config WHERE config.exercise_id = exercise.id);

rollback.sql:
DELETE FROM tutorial_groups_configuration
                WHERE tutorial_period_start_inclusive IS NULL AND tutorial_period_end_inclusive IS NULL
                AND NOT EXISTS (SELECT 1 FROM tutorial_group_free_period period WHERE period.tutorial_groups_configuration_id = tutorial_groups_configuration.id);
                DELETE FROM online_course_configuration
                WHERE lti_platform_id IS NULL AND require_existing_user = FALSE
                AND course_id IN (SELECT id FROM course WHERE online_course IS NULL OR online_course = FALSE);
